insert into hub.meetings (id, meeting_date, kind, source_doc_id, summary, vote_notes) values
('2026-04-22','2026-04-22','regular','minutes-2026-04-22',array['Approved the treasurer''s report, payment of bills, and fund transfers.','First reading of a revision to the animal-control ordinance (06-0321-A) adding a trap-neuter-vaccinate-return program for community cats.','Adopted Resolution 26-0422-A executing the County Road Aid agreement with the state Transportation Cabinet.','Awarded FY2026-27 road-material and service bids (aggregate, asphalt, fuel, paving and more); rejected the red-gravel bids for resubmission.','Awarded fire-extinguisher service to Fire Safe Services and county-facility pest control to McGee Pest Control (about $667/year savings).','Approved an amended 2026 budget (no change to the bottom line) and a CD renewal at The Murray Bank.','Approved a 4-year, $365,000 loan at 4.53% (FNB Bank) to purchase two dump trucks.']::text[],'{}'::text[]),
('2026-03-20','2026-03-20','regular','minutes-2026-03-20',array['Approved the financial statement, bills, and cash transfers.','Second reading and adoption of Ordinance 20-0320-A, a budget amendment involving Sheriff''s funds.','Approved the County Clerk''s 2025 final settlement.','Adopted Resolution 26-0320-C (agreement with the state Transportation Cabinet) for replacement of the Howard Road bridge, funded through CCBIP at $800,000.','Adopted Resolution 26-0320-D supporting a grant application (up to about $1 million) toward a new fire station, and 26-0320-E supporting agricultural hemp development.','Made board appointments to the Industrial Development Authority and the hospital (MCCH) board; approved revised job descriptions.']::text[],'{}'::text[]),
('2026-02-18','2026-02-18','regular','minutes-2026-02-18',array['Approved the financial report and payment of bills; approved 2026 incentive pay for several officials.','Approved the Sheriff''s 2025 excess-fee final settlement and agreed to return $202,189.26 to the Sheriff''s office, disbursed quarterly (March-June), with a related budget-amendment first reading.','Adopted Resolution 26-0218-A (adopting Sack Farm Drive for 911 addressing), 26-0218-B (authorizing application for KY Homeland Security grants), and 26-0218-C (supporting HB 557, cited as benefiting the jail budget).','Reappointed members to the Ethics Board.','Held the Grubbs Road bridge bids until the next meeting to standardize a 20-foot width.','Entered executive session under KRS 61.810(1)(f); returned with no action taken.']::text[],'{}'::text[]),
('2026-01-21','2026-01-21','regular','minutes-2026-01-21',array['Approved the treasurer''s report, bills, and cash transfers; approved a contract with ACA Prime for 1095 health-insurance forms.','Adopted resolutions honoring a retiring jail deputy (26-0121-A), memorializing the late Magistrate Johnny Gingles (26-0121-B), and joining the America250KY Liberty Tree planting (26-0121-C).','Made board appointments to the Hazel 641 Water District.','Approved a contract with Shelter Planners of America for a first-step survey toward a new animal shelter.','Discussed a joint Community Development Block Grant application with the City of Murray to renovate the Senior Citizens Center; the Judge-Executive disclosed a conflict of interest and said he would abstain on that matter.']::text[],'{}'::text[]),
('2025-12-17','2025-12-17','regular','minutes-2025-12-17',array['Approved the financial statement, bills, and budget/cash transfers.','Approved the 2026 County Clerk budget and salary order and set election-worker pay at $250.','Approved the 2026 holiday and meeting schedule.','Adopted resolutions recognizing local students and the Murray High football team; discontinuing county maintenance on Nova Lane (after a public hearing with no comment); supporting an MCIDA training-center grant application (25-1217-D); and a Transportation Cabinet agreement for the Potts Road bridge using CCBIP funds (25-1217-E).','Renewed the EMS affiliation agreement with Calloway County Fire-Rescue and approved the surplus of two Sheriff''s vehicles.']::text[],'{}'::text[]),
('2025-11-19','2025-11-19','regular','minutes-2025-11-19',array['Approved the financial statement, bills, and transfers.','Approved the 2026 Sheriff''s budget and the annual order setting maximum Sheriff''s-office salaries at $2,200,000.','Adopted Resolution 25-1119-A for a CCBIP agreement with the Transportation Cabinet to repair/replace the Graham Road bridge (state-managed work).','Created a county Cemetery Board (five members) and reappointed/appointed UK Cooperative Extension board members.','Awarded the Doores Trail culvert-to-bridge project to Youngblood at $415,389 (FEMA-submitted).']::text[],'{}'::text[]),
('2025-10-15','2025-10-15','regular','minutes-2025-10-15',array['Approved the financial statement.','Approved jail firearms-policy updates.','Authorized a Regional Development Agency Assistance Program application of $153,846 toward a Workforce Training Center, and signed an Emergency Management Performance Grant.','Authorized a FEMA-grant culvert replacement on Doores Trail (county share is a portion of a statewide allocation).','Approved changing the county cellular provider from Verizon to T-Mobile, and authorized an interlocal agreement with the City of Murray for the Weaks Senior Citizens Center grant.']::text[],'{}'::text[]),
('2025-09-24','2025-09-24','regular','minutes-2025-09-24',array['Approved the financial statement, bills, and transfers.','Second reading and adoption of Ordinance 25-0924-A regulating medical-cannabis business operations (public hearing, no comment).','Adopted a resolution discontinuing road maintenance on Eldridge Lane and began the removal process for Nova Lane and East Y Road.','Made appointments to the Tourism Commission, Dexter-Almo Water District, 911 Appeals Board, and Library Board.','Authorized listing the remaining five county-owned lots in Western Shores; authorized Road Department fall maintenance on the Hwy 641 lot (per Resolution 24-0717-A requiring full-Court consent).']::text[],'{}'::text[]),
('2025-08-20','2025-08-20','regular','minutes-2025-08-20',array['Approved the financial statement, bills, and cash transfers.','Second reading and adoption of Ordinance 25-0821-A setting the 2025 county tax rates (public hearing, no comment).','First reading of an ordinance regulating medical-cannabis operations.','Heard special taxing-district rates (Library 4.8c real property; Extension 2.5c, up from 1.5c, citing reserve drawdown).','Adopted resolutions accepting Victory Lane into the county road system (25-0820-E), accepting 2025 FLEX funds (25-0820-D), and supporting a DRA grant for Hopkins Road (25-0820-C).','Entered executive session under KRS 61.810(1)(f) and (1)(b).']::text[],'{}'::text[]),
('2025-07-16','2025-07-16','regular','minutes-2025-07-16',array['Approved the financial statement, bills, transfers, and a $100,000 transfer to the Road Department.','First reading of the 2025 county tax rate at 14.10 cents/$100 — described as 4% over the compensating rate, an estimated ~$29,000 in added revenue (rate last increased in 2021).','Adopted the EM State Mutual Aid agreement and resolution 25-0716-A.','Awarded a $73,600 contract to Henry and Son to paint the courthouse; approved an HVAC replacement (Thornton''s) for the EM office.','Approved an updated drug-testing contract (Tri-State), with a rebid to follow per the two-year requirement.']::text[],array['Street-Legal Special Purpose Vehicle ordinance 25-0716-A (second reading): passed 4-1 — Squire Cherry voted no; Judge Imes and Squires Rister, Crutcher, Stewart voted aye.']::text[]),
('2025-06-30-special','2025-06-30','special','minutes-2025-06-30-special',array['Approved a $529.22 budget transfer to the County Attorney salary line.','Authorized a $300,000 transfer (money market to general to jail) to cover July jail insurance and workers''-comp bills.','Adopted a resolution for a Transportation Cabinet agreement to repair/replace the Charley Miller Road bridge with grant funds up to $490,000.','Discussed (no action) a ~$1.8M CCBIP award (7.3% of the first $25M round) for four bridges, and an $51,805 KYTC 80/20 swap from Grubbs Road to Cook Store bridge (about $6,000 added from road funds).']::text[],'{}'::text[]),
('2025-06-18','2025-06-18','regular','minutes-2025-06-18',array['Approved the financial statement, bills, transfers, and the second reading of budget amendment 25-0618-A (Flex Funds).','Set the Health Department tax rates for 2026 (unchanged).','Approved the Sheriff''s 2024 tax settlement.','Adopted Resolution 25-0618-A (administrative-code amendments) and 25-0618-B (supporting the Job Corps program).','Approved a 2.9% cost-of-living increase for non-elected county employees and appointed Chris Franklin as Road Supervisor (KRS 179.020).','Discontinued Sharmae Lane and adjusted John Purdom/Harry Truman drive names.']::text[],'{}'::text[]),
('2025-05-21','2025-05-21','regular','minutes-2025-05-21',array['Approved the financial report, bills, transfers, and first reading of a Flex-funds budget amendment.','Second reading and adoption of the 2025-2026 county budget (public hearing, no comment).','Adopted Resolution 25-0521-A (Transportation Cabinet agreement) for replacement of the Clayton Town Road bridge.','Approved a $89,629 Grubbs Road bridge repair contract (Jim Smith Contracting) and a 4-year paving agreement for 3.58 miles in Western Shores.','Authorized a purchase order for two dump trucks (~$174,000 each, delivery in 2026) and a $1,500 TVA 26A permit application for the Boatwright Trail project.']::text[],'{}'::text[]),
('2025-05-12-special','2025-05-12','special','minutes-2025-05-12-special',array['Special session on the disposition of the old Old Salem Road bridge after the new bridge''s completion.','Approved, by general consensus (all ayes), keeping the historic structure for community use as a small fishing/nature area, with KACO consulted on liability and Fish & Wildlife on collaboration.']::text[],'{}'::text[]),
('2025-04-28-special','2025-04-28','special','minutes-2025-04-28-special',array['Authorized a $1,500,000 12-month CD at The Murray Bank (4.25% APY) funded from the jail-grant account, and a $625,000 12-month CD (4.25% APY) funded from the E911 account, with matching budget line items added.','Approved issuing an RFP (two-week timeline) for the Grubbs Road bridge, weighing closure against an estimated $91,000 repair.','Discussed (no action) the 2026-2027 County Priority Project Program.']::text[],'{}'::text[]),
('2025-04-16','2025-04-16','regular','minutes-2025-04-16',array['Approved the financial report, bills, second reading of a budget amendment (Sheriff excess fees and the 80/20 bridge program), the annual standing order, and a cash-transfer blanket order.','Accepted reduced LGEA funds ($8,000 down to $6,000) and noted a MAG block-grant payment of $163,980 (third payment).','Adopted Resolution 25-0416-A for the County Road Aid Cooperative Program ($1,649,680.39 for FY beginning July 1, 2025).','First reading of the 2025-2026 county budget totaling $20,277,141.58.','First reading of the street-legal special-purpose-vehicle ordinance (SB 63 opt-in); reauthorized standing committees and added a Long Range Planning & Financing committee.']::text[],'{}'::text[]),
('2025-03-24-special','2025-03-24','special','minutes-2025-03-24-special',array['Adopted Resolution 25-0324-A for a Rural Secondary Program agreement with the Transportation Cabinet to address drainage at the Dodd Road bridge.','Entered and exited executive session under KRS 61.810(1)(f) with no action taken.']::text[],'{}'::text[]),
('2025-03-19','2025-03-19','regular','minutes-2025-03-19',array['Approved the financial report, bills, transfers, and a first-reading budget amendment (Sheriff excess fees and 80/20 bridge funds).','Noted a $157,227 MAG block-grant payment (second payment) to Clark Construction.','Approved the County Clerk''s 2024 final settlement and recurring 911 software contracts (Active911, Virtual Academy).','Adopted a PADD/Murray Art Guild CDBG administration resolution (25-0319-E) and resolutions honoring community members.','Noted the jail budget''s $430,000 personnel-line increase tied to the salary survey.']::text[],'{}'::text[]),
('2025-02-19','2025-02-19','regular','minutes-2025-02-19',array['Approved the financial report and bills, including a $83,862 MAG block-grant payment to Clark Construction.','Approved the Sheriff''s 2024 final settlement ($259,727.37 turned over) and returned the funds for deputy salaries in four payments.','Adopted resolutions for Transportation Cabinet agreements on the Clayton Road bridge ($430,000) and Furches Trail bridge ($505,000), and a Homeland Security application (24-0219-E).','Confirmed a $1,786,301 25% local match (G.R.A.N.T./HB 9) tied to a WK&T USDA ReConnect award for ~94 miles of fiber.','Approved the lowest Taylor Store bridge bid ($143,626, Jim Smith Construction) and up to $35,000 for Almo bridge repairs.']::text[],'{}'::text[]),
('2025-01-15','2025-01-15','regular','minutes-2025-01-15',array['Approved the financial statement, bills, and a transfer.','Approved 911 policy changes and the annual Calloway County Fire-Rescue affiliation.','Heard 2024 jail and sheriff reports; noted research on 1,506 unpaid 2023 property-tax bills and related legislation (KRS 132.012).','Entered executive session under KRS 61.810(1)(b) on personnel matters; returned with no action.']::text[],'{}'::text[]),
('2024-12-18','2024-12-18','regular','minutes-2024-12-18',array['Approved the financial statement, bills, transfers, and a $180,062.50 check (on delivery) for a Road Department dump truck.','Approved Sheriff and Clerk administrative-code changes and the 2025 County Clerk budget and salary order.','Approved the 2025 holiday/meeting schedule (12 observed holidays).','Adopted Resolution 24-1218-A (revised administrative code, part-time holiday pay), 24-1218-B (remaining ARPA funds for the Old Salem Road bridge), and 24-1218-C (designating MCIDA to receive TVA funds).','Noted 2024 auto-insurance-premium-tax use: $1.1M for paving and $700K allocated for bridges; authorized TVA permit applications for Boatwright Landing and Chandler Park.']::text[],array['Grounds-maintenance contract (Swift Environmental): passed 4-1 — Judge Imes voted no.','Tourism Commission appointments: Squire Rister abstained (board member).']::text[]),
('2024-10-16','2024-10-16','regular','minutes-2024-10-16',array['Approved the financial statement, bills, and cash transfers.','Amended the Sheriff''s 2024 budget (reflecting returned excess fees) and approved jail-policy updates.','Second reading and adoption of amendments to the Solar Farm ordinance 24-0417-A (public hearing, no comment).','Adopted Resolution 24-1016-A for the 80/20 KYTC bridge program (up to $80,000 reimbursement toward a $100,000+ five-bridge project) and 24-1016-C naming two private drives for 911.','Approved 911 purchases: a Nelson Systems maintenance renewal ($13,627.53) and three solar battery-backup systems for radio towers ($17,160).']::text[],'{}'::text[]),
('2024-09-18','2024-09-18','regular','minutes-2024-09-18',array['Approved the financial statement, bills, and transfers.','Held a public hearing and adopted the 2024-25 tax rate at $0.14/$100.','First reading of an amendment to the Solar Farm ordinance 24-0417-A (floating systems, TVA/PSC rules, fees).','Approved an ER Assist contract for FEMA debris-removal coordination after the May storm (with a local-hire provision).','Adopted Resolution 24-0918-A (drug- and alcohol-free workplace policy) and 24-0918-B (new job descriptions); dismissed the 911 Relocation Committee (no relocation).']::text[],array['2024-25 county tax rate ($0.14 per $100): passed 4-1 — Squire Crutcher voted no; Judge Imes and Squires Rister, Cherry, Stewart voted aye.']::text[]),
('2024-07-17','2024-07-17','regular','minutes-2024-07-17',array['Approved the financial statement, bills, transfers, and the 2023-2024 Treasurer''s settlement.','Approved the Sheriff''s 2023 tax settlement.','Placed a medical-cannabis question on the 2024 ballot by resolution (see vote note).','Approved the jail''s purchase of a 2017 minivan for inmate transport ($5,000); noted a $4,396 jail taser grant.']::text[],array['Resolution 24-0717-A (no action on the 641 & 80 property without full-Court approval at an open meeting): passed with Judge Imes abstaining (four ayes).','Cannabis-referendum resolution for the 2024 ballot (as amended): roll-call passed 3-2 — Squires Stewart, Crutcher, Cherry aye; Squire Rister and Judge Imes nay. (The amendment adding the ballot wording passed unanimously first.)']::text[]),
('2024-06-28-special','2024-06-28','special','minutes-2024-06-28-special',array['Adopted Resolution 24-0628-A approving the revised Calloway County Administrative Code.','Adopted Resolution 24-0628-B authorizing transfer of Nelom Brown Drive to the National Park Service.','Approved a budget transfer and authorized payment from LAFTA funds for an Animal Shelter vehicle.','Held discussion (no vote) on the draft medical-cannabis ordinance ahead of the state opening dispensary applications July 1.']::text[],'{}'::text[]),
('2024-05-15','2024-05-15','regular','minutes-2024-05-15',array['Approved the financial statements, bills, cash and budget transfers, and additional payments to Jim Smith Contracting and Murray Paving.','First reading of a 2023-2024 budget amendment for KYTC emergency funds (Coleman Branch and Squire Holland bridges).','Created a new Auto Insurance Tax line item and opened a dedicated Murray Bank account, transferring $942,317.37 from the Road Fund into it.','Adopted Resolution 24-0515-A (County Road Aid Cooperative Program agreement).','Second reading and adoption of the 2024-2025 county budget; first readings of road-acceptance-requirements and medical-cannabis ordinances; accepted Westhaven Lane into the county road system.']::text[],array['Medical-cannabis ballot-question resolution: a motion was made but received no second; it was laid on the clerk''s desk with no vote taken.']::text[]),
('2024-04-17','2024-04-17','regular','minutes-2024-04-17',array['Approved the financial statements, bills, cash transfers, and the second reading of a budget amendment (public hearing, no comment).','Approved the annual standing order and a blanket cash-transfer order for FY2024-25.','First reading of the FY2024-2025 county budget.','Second reading and adoption of the Solar Farm ordinance 24-0417-A (public hearing; supportive comment from KY Farm Bureau).','Adopted Resolution 24-0417-A (discontinuing Ft. Heiman Road and Nelom Brown Drive) and 24-0417-B (Public Safety Telecommunications Week).']::text[],'{}'::text[]),
('2024-03-20','2024-03-20','regular','minutes-2024-03-20',array['Approved the financial statements, bills, cash transfers, budget transfers, and a first-reading budget amendment.','Approved the County Clerk''s 2023 final settlement ($179,475).','First reading of a solar-energy-system licensing ordinance (public hearing/second reading set for April).','Began the KRS process to remove Ft. Heiman Road and Nelom Brown Road from county maintenance (pending National Park Service deed transfer).','Split the county pest-control contract between Bug Master and McGee; adopted Homeland Security (24-0320-A) and road/PADD/CDBG resolutions (24-0320-B through -G).']::text[],'{}'::text[]),
('2024-02-21','2024-02-21','regular','minutes-2024-02-21',array['Approved the financial statements and bills.','Approved the Sheriff''s final settlement ($242,673.22 in excess fees turned over) and returned the funds for deputy support over four months (March-June).','Approved a Regional Mutual Aid Agreement and accepted Hill Drive and Landon Lane into the county road system.','Discontinued a portion of Mills Trail after a public-comment period (deemed to serve no public purpose by two viewers and the Road Supervisor).','Reappointed two members to the Weaks Center Board.']::text[],'{}'::text[]),
('2024-01-24','2024-01-24','regular','minutes-2024-01-24',array['Approved the financial statements and payment of bills.','Authorized moving forward on Coleman Branch and Squire Holland bridge repairs (Jim Smith Contracting), pending an 80/20 state grant match.','Heard 2023 jail and sheriff reports.','Adopted Resolution 24-0124-A (accepting Edinborough Drive West and Starview Trail into the county road system), 24-0124-B (Regional Transportation Safety Action Plan), and 24-0124-C (honoring an Eagle Scout).','Appointed a Fiscal Court member to the hospital Personnel Committee and named EM volunteer deputy directors by executive order.']::text[],'{}'::text[]) on conflict (id) do nothing;
